/// The SDK's own words, in the visitor's language. A port of the web
/// widget's conferbot-widget/src/ts/i18n.ts by way of the React Native SDK's
/// src/core/i18n.ts; the tables (strings_<lang>.dart, generated by
/// tool/sync_i18n.sh from RN's scripts/parity/i18n/strings.json) are the
/// web's keys and words, plus the `sdk.*` words only the SDKs draw.
///
///   t(key, vars)              the active language's string, {name} filled in
///   I18n.tFor(lang, key, vars) the same for a given language (pure, for tests)
///   tPlural(base, n)          `base.one` for 1, else `base.other`
///   I18n.resolveLanguage(setting, deviceLanguages)
///                             a set language wins; "auto", unset or unknown
///                             picks the first supported device language,
///                             else English
///   I18n.setWidgetLanguage(setting) when the bot's settings arrive, before
///                             the chat is drawn (the provider does it)
///
/// In an app "auto" means the phone's languages, most preferred first
/// (Flutter's PlatformDispatcher.locales; the web reads navigator.languages).
/// Only the SDK's chrome lives here: what the owner wrote is shown as
/// written, except the stock English defaults a new bot is made with
/// ([I18n.stockText], [I18n.ownerTextOr]).
///
/// A key missing from a language falls back to English, then to the key
/// itself, so a half-finished translation never shows a blank.
library;

import 'package:flutter/foundation.dart';
import 'package:intl/date_symbol_data_local.dart' show dateTimeSymbolMap, initializeDateFormatting;
import 'package:intl/date_symbols.dart' show DateSymbols;

import 'i18n_strings.dart';

class I18n {
  I18n._();

  static const String en = 'en';

  /// The languages the widget speaks, English first.
  static const List<String> supported = i18nLanguages;

  /// Each language's own name, for pickers.
  static const Map<String, String> languageNames = i18nLanguageNames;

  /// Every key in the table (the web's, then sdk.*).
  static const List<String> keys = i18nKeys;

  /// One language's words by key (no fallback), for tests and the sync check.
  static Map<String, String> dictionary(String lang) => i18nTableOf(_isSupported(lang) ? lang : en);

  static bool _isSupported(Object? v) => v is String && supported.contains(v);

  /// A stored setting: a supported code, else "auto" (old bots have none).
  static String normalizeWidgetLanguage(Object? raw) {
    final v = raw is String ? raw.trim().toLowerCase() : '';
    return _isSupported(v) ? v : 'auto';
  }

  /// "nl-BE" -> "nl"; anything unsupported -> null.
  static String? baseLanguageOf(Object? tag) {
    if (tag is! String) return null;
    final base = tag.trim().toLowerCase().split(RegExp(r'[-_]')).first;
    return _isSupported(base) ? base : null;
  }

  /// The language to draw in: the chosen one, or the first supported device
  /// language, or English.
  static String resolveLanguage(Object? setting, [List<String>? deviceLanguages]) {
    final chosen = normalizeWidgetLanguage(setting);
    if (chosen != 'auto') return chosen;
    for (final tag in deviceLanguages ?? const <String>[]) {
      final base = baseLanguageOf(tag);
      if (base != null) return base;
    }
    return en;
  }

  /// The phone's languages, most preferred first, as BCP 47 ("de-DE"); the
  /// app's locale when the list is empty. Flutter's "und" and repeats dropped.
  static List<String> deviceLanguages([PlatformDispatcher? dispatcher]) {
    final out = <String>[];
    try {
      final d = dispatcher ?? PlatformDispatcher.instance;
      for (final l in [...d.locales, d.locale]) {
        final tag = l.toLanguageTag();
        if (tag.isEmpty || tag.toLowerCase().startsWith('und') || out.contains(tag)) continue;
        out.add(tag);
      }
    } catch (_) {
      // No platform (plain Dart): none.
    }
    return out;
  }

  static final RegExp _placeholder = RegExp(r'\{(\w+)\}');

  static String _fill(String text, Map<String, Object?>? vars) {
    if (vars == null || vars.isEmpty) return text;
    return text.replaceAllMapped(_placeholder, (m) {
      final v = vars[m.group(1)];
      return v == null ? m.group(0)! : _valueText(v);
    });
  }

  // Whole numbers without ".0", as JS writes them.
  static String _valueText(Object v) {
    if (v is double && v.isFinite && v == v.truncateToDouble() && v.abs() < 1e15) return v.toInt().toString();
    return v.toString();
  }

  /// A string in a given language, {name} placeholders filled.
  static String tFor(String lang, String key, [Map<String, Object?>? vars]) {
    final text = dictionary(lang)[key] ?? i18nTableOf(en)[key] ?? key;
    return _fill(text, vars);
  }

  static final ValueNotifier<String> _language = ValueNotifier<String>(en);
  static String _activeTag = en;

  /// The language being drawn in, for widgets that redraw when it changes.
  static ValueListenable<String> get languageListenable => _language;

  /// The language being drawn in.
  static String get language => _language.value;

  /// A BCP 47 tag for dates (e.g. "nl-BE"): the device's regional tag of the
  /// active language, else the language.
  static String get localeTag => _activeTag;

  static final RegExp _regional = RegExp(r'^[a-zA-Z]{2}[-_][a-zA-Z]{2}$');

  /// Picks the language to draw in; returns it. [languages] defaults to the
  /// phone's.
  static String setWidgetLanguage(Object? setting, [List<String>? languages]) {
    final langs = languages ?? deviceLanguages();
    final active = resolveLanguage(setting, langs);
    // A regional tag of the same language keeps its region for dates
    // (nl-BE writes dates the Belgian way).
    String? regional;
    for (final tag in langs) {
      if (baseLanguageOf(tag) == active) {
        regional = tag;
        break;
      }
    }
    _activeTag = regional != null && _regional.hasMatch(regional) ? regional.replaceAll('_', '-') : active;
    ensureDateFormatting();
    _language.value = active;
    return active;
  }

  /// A string in the active language, {name} placeholders filled.
  static String t(String key, [Map<String, Object?>? vars]) => tFor(language, key, vars);

  /// "{n} thing" vs "{n} things": the `.one` key for 1, else `.other`.
  static String tPlural(String base, num n, [Map<String, Object?>? vars]) =>
      t('$base.${n == 1 ? 'one' : 'other'}', {'n': n, ...?vars});

  /// An intl locale for dates in the active language ("nl_BE", else "nl").
  static String get intlLocale {
    final symbols = dateTimeSymbolMap();
    final tag = _activeTag.replaceAll('-', '_');
    if (symbols.containsKey(tag)) return tag;
    return symbols.containsKey(language) ? language : en;
  }

  static bool _datesReady = false;

  /// Loads intl's date names for every locale (synchronous: the data is
  /// built in), so DateFormat(pattern, I18n.intlLocale) works.
  static void ensureDateFormatting() {
    if (_datesReady) return;
    _datesReady = true;
    try {
      initializeDateFormatting();
    } catch (_) {
      _datesReady = false;
    }
  }

  static DateSymbols? _symbols() {
    try {
      return dateTimeSymbolMap()[intlLocale] as DateSymbols?;
    } catch (_) {
      return null;
    }
  }

  /// The week's day names, Sunday first, in the widget's language: "long",
  /// "short" (Sun, zo, dim.) or "narrow" (S, Z, D). English keeps the SDK's
  /// own spellings for [english].
  static List<String> weekdayNames([String style = 'short', List<String>? english]) {
    if (language == en && english != null) return english;
    final s = _symbols();
    if (s == null) return english ?? const ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    final names = style == 'long'
        ? s.STANDALONEWEEKDAYS
        : style == 'narrow'
            ? s.STANDALONENARROWWEEKDAYS
            : s.STANDALONESHORTWEEKDAYS;
    return List<String>.of(names);
  }

  /// Month names, January first, in the widget's language ("short": Jan, janv.).
  static List<String> monthNames([String style = 'short', List<String>? english]) {
    if (language == en && english != null) return english;
    final s = _symbols();
    if (s == null) {
      return english ?? const ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    }
    return List<String>.of(style == 'long' ? s.STANDALONEMONTHS : s.STANDALONESHORTMONTHS);
  }

  static String _plain(String s) => s
      .replaceAll(RegExp(r'<[^>]*>'), '')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim()
      .replaceAll(RegExp(r'[.!]$'), '')
      .toLowerCase();

  static bool _isStock(String value, String key, List<String> stockEnglish) {
    final v = _plain(value);
    return [tFor(en, key), ...stockEnglish].any((s) => _plain(s) == v);
  }

  /// An owner field that may still hold the stock English default (stored by
  /// an older dashboard): empty or the default is shown in the visitor's
  /// language, a value the owner wrote themselves as written.
  static String ownerTextOr(Object? value, String key, [List<String> stockEnglish = const []]) {
    if (value is! String || _plain(value).isEmpty || _isStock(value, key, stockEnglish)) return t(key);
    return value;
  }

  /// A field a new bot is created with in English ("Hi there 👋"): that exact
  /// stock value is shown in the visitor's language. Empty stays empty, and
  /// anything the owner wrote is theirs.
  static String stockText(Object? value, String key, [List<String> stockEnglish = const []]) {
    if (value is! String) return '';
    if (value.trim().isEmpty) return value;
    return _isStock(value, key, stockEnglish) ? t(key) : value;
  }

  /// Tests: back to English, the device's languages forgotten.
  @visibleForTesting
  static void debugReset() {
    _activeTag = en;
    _language.value = en;
  }
}

/// A string in the active language, {name} placeholders filled (web i18n t).
String t(String key, [Map<String, Object?>? vars]) => I18n.t(key, vars);

/// "{n} thing" vs "{n} things" in the active language.
String tPlural(String base, num n, [Map<String, Object?>? vars]) => I18n.tPlural(base, n, vars);
